editorial:
Sum the first k values and initialize the answer from that window, including if it is negative. When advancing, add the entering value and subtract the leaving one. Each move then takes constant time. Total time O(n), with O(n) storage for the array.
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n,k; cin>>n>>k;
    vector<long long>a(n);
    for (auto& x:a) cin>>x;
    long long sum=accumulate(a.begin(),a.begin()+k,0LL),best=sum;
    for (int r=k;r<n;++r) {
        sum+=a[r]-a[r-k];
        best=max(best,sum);
    }
    cout<<best<<'\n';
}
